#include "NifFile.hpp"
#include <fstream>
#include <iomanip>
#include <iostream>
using namespace nifly;
int wmain(int argc,wchar_t**argv){if(argc!=3)return 1;NifFile n;if(n.Load(std::filesystem::path(argv[1]))||!n.IsValid())return 2;std::ofstream o{std::filesystem::path(argv[2])};o<<std::setprecision(9)<<"{\"root\":"<<std::quoted(n.GetRootNode()->name.get())<<",\"shapes\":[";bool first=true;
for(auto*s:n.GetShapes()){if(!first)o<<",";first=false;auto*v=n.GetVertsForShape(s);auto*uv=n.GetUvsForShape(s);auto*no=n.GetNormalsForShape(s);std::vector<Triangle>tr;s->GetTriangles(tr);auto*sp=dynamic_cast<BSShaderProperty*>(n.GetShader(s));o<<"{\"name\":"<<std::quoted(s->name.get())<<",\"id\":"<<n.GetHeader().GetBlockID(s)<<",\"skinRef\":"<<s->SkinInstanceRef()->index<<",\"shaderRef\":"<<s->ShaderPropertyRef()->index<<",\"alphaRef\":"<<s->AlphaPropertyRef()->index<<",\"flags\":"<<s->flags<<",\"shader1\":"<<(sp?sp->shaderFlags1:0)<<",\"shader2\":"<<(sp?sp->shaderFlags2:0)<<",\"doubleSided\":"<<(sp&&sp->IsDoubleSided()?"true":"false")<<",\"textures\":[";for(int k=0;k<6;k++){std::string t;n.GetTextureSlot(s,t,k);if(k)o<<",";o<<std::quoted(t);}o<<"],\"vertices\":[";for(size_t k=0;k<v->size();k++){if(k)o<<",";auto&p=v->at(k);o<<"["<<p.x<<","<<p.y<<","<<p.z<<"]";}o<<"],\"normals\":[";if(no)for(size_t k=0;k<no->size();k++){if(k)o<<",";auto&p=no->at(k);o<<"["<<p.x<<","<<p.y<<","<<p.z<<"]";}o<<"],\"uvs\":[";if(uv)for(size_t k=0;k<uv->size();k++){if(k)o<<",";auto&p=uv->at(k);o<<"["<<p.u<<","<<p.v<<"]";}o<<"],\"triangles\":[";for(size_t k=0;k<tr.size();k++){if(k)o<<",";o<<"["<<tr[k].p1<<","<<tr[k].p2<<","<<tr[k].p3<<"]";}o<<"]}";}o<<"]}";return 0;}